	private void updateSubTitle() {
		StringBuilder builder = new StringBuilder();
		builder.append(" ");
		int count = tableModel.getUnfilteredRowCount();
		if (count > 0) {
			builder.append("(");
			builder.append(count);
			builder.append(count == 1 ? " item)" : " items)");
