		private List<QuickFix> quickFixList;

		public ApplyItemsTask(Program program, string title, List<QuickFix> quickFixList) : base(program, title, true, true, true)
    {
			this.quickFixList = quickFixList;
		}

		/* @Override */
		protected void doRun(TaskMonitor monitor) {
			foreach (QuickFix quickFix in quickFixList) {
				quickFix.performAction();
			}
		}

	}

